import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

results = {}

# Search up to N=500 for a reasonable initial small search
N_max = 500

for n in range(1, N_max + 1):
    if tau(n) >= 5:
        divisors = get_divisors(n)

        # We need at least 5 divisors
        if len(divisors) >= 5:
            # Divisors are sorted: d1, d2, d3, d4, d5, ...
            # d1 is always 1.
            a = divisors[1]  # Second smallest
            b = divisors[2]  # Third smallest
            c = divisors[4]  # Fifth smallest

            # Check the condition: ab + ac + bc = n
            condition_met = (a * b + a * c + b * c == n)

            if condition_met:
                t = tau(n)
                if t not in results:
                    results[t] = []
                results[t].append(n)

print("Found tau(n) values:")
print(results)

