import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    if n == 1:
        return 1
    count = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
        d += 1
    return count

def solve_problem_search(N_limit):
    results = {}
    print(f"Starting search up to N = {N_limit}...")

    # Start from the smallest n with at least 5 divisors (n=12)
    for n in range(12, N_limit + 1):
        divisors = get_divisors(n)

        # Check requirement: at least 5 positive divisors
        if len(divisors) < 5:
            continue

        # Identify a, b, c: 2nd, 3rd, 5th smallest divisors
        # divisors[0] is 1 (d1)
        # a = d2, b = d3, c = d5
        try:
            a = divisors[1]
            b = divisors[2]
            c = divisors[4]
        except IndexError:
            # Should not happen if len(divisors) >= 5
            continue

        # Check the equation: (a + b + c)^2 = a^2 + b^2 + c^2 + 2n
        # Simplified: n = ab + ac + bc
        LHS_n = a * b + a * c + b * c

        if LHS_n == n:
            tau_n = tau(n)
            results[n] = tau_n
            print(f"Found solution n={n}, tau(n)={tau_n}. Divisors: {divisors}")

    return results

N_limit = 10000
solution_set = solve_problem_search(N_limit)

if solution_set:
    print("\n--- Summary of Solutions Found (N <= 10000) ---")
    print(f"All found solutions (n, tau(n)): {solution_set}")
else:
    print("\nNo solutions found in the range N <= 10000.")
